const ASCII_CASING_FAST_PATH: bool = true;

use super::{JsString, categories, push_char, whitespace};

pub(super) fn lower(text: &JsString) -> JsString {
    lower_with(text, ASCII_CASING_FAST_PATH)
}
pub(super) fn upper(text: &JsString) -> JsString {
    upper_with(text, ASCII_CASING_FAST_PATH)
}
fn lower_with(text: &JsString, fast: bool) -> JsString {
    if fast && text.units().iter().all(|unit| *unit < 128) {
        return JsString::from_units(
            text.units()
                .iter()
                .map(|unit| {
                    if (65..=90).contains(unit) {
                        unit + 32
                    } else {
                        *unit
                    }
                })
                .collect(),
        );
    }
    text.lower()
}
fn upper_with(text: &JsString, fast: bool) -> JsString {
    if fast && text.units().iter().all(|unit| *unit < 128) {
        return JsString::from_units(
            text.units()
                .iter()
                .map(|unit| {
                    if (97..=122).contains(unit) {
                        unit - 32
                    } else {
                        *unit
                    }
                })
                .collect(),
        );
    }
    // Whole well-formed runs retain Unicode expansion and contextual casing;
    // invalid UTF16 units survive exactly, as in the existing lower helper.
    let mut output = Vec::with_capacity(text.len());
    let mut run = String::new();
    for character in char::decode_utf16(text.units().iter().copied()) {
        match character {
            Ok(character) => run.push(character),
            Err(error) => {
                output.extend(run.to_uppercase().encode_utf16());
                run.clear();
                output.push(error.unpaired_surrogate());
            }
        }
    }
    output.extend(run.to_uppercase().encode_utf16());
    JsString::from_units(output)
}
pub(super) fn capitalize(text: &JsString) -> JsString {
    capitalize_with(text, ASCII_CASING_FAST_PATH)
}
fn capitalize_with(text: &JsString, fast: bool) -> JsString {
    let Some(first) = text.units().first() else {
        return JsString::default();
    };
    // JavaScript text[0] selects one UNIT, even if it splits a surrogate pair.
    let first = upper_with(&JsString::from_units(vec![*first]), fast);
    let mut output = Vec::with_capacity(first.len() + text.len() - 1);
    output.extend_from_slice(first.units());
    output.extend_from_slice(&text.units()[1..]);
    JsString::from_units(output)
}
pub(super) fn title(text: &JsString) -> JsString {
    title_with(text, ASCII_CASING_FAST_PATH)
}
fn title_with(text: &JsString, fast: bool) -> JsString {
    let lower = lower_with(text, fast);
    let mut output = Vec::with_capacity(lower.len());
    let mut word_start = true;
    if fast && lower.units().iter().all(|unit| *unit < 128) {
        for &unit in lower.units() {
            output.push(if word_start && (97..=122).contains(&unit) {
                unit - 32
            } else {
                unit
            });
            word_start = whitespace(unit);
        }
        return JsString::from_units(output);
    }
    for character in char::decode_utf16(lower.units().iter().copied()) {
        match character {
            Ok(character) => {
                if word_start && categories(character).0 {
                    for upper in character.to_uppercase() {
                        push_char(&mut output, upper);
                    }
                } else {
                    push_char(&mut output, character);
                }
                word_start = crate::utils::js_compat::is_whitespace(character);
            }
            Err(error) => {
                output.push(error.unpaired_surrogate());
                word_start = false;
            }
        }
    }
    JsString::from_units(output)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ascii_and_generic_routes_have_identical_utf16_results() {
        let mut inputs = vec![
            JsString::from(""),
            JsString::from("hello WORLD\tNext\r\nlast !word foo-bar"),
            JsString::from("straße ﬃ ΟΣ İ 𐐨"),
            JsString::from("\u{85}ABC\u{feff}DEF\u{301}GHI"),
            JsString::from_units(vec![0xd800, 65, 0xdc00, 32, 0x03a3]),
            JsString::from_units((0..128).collect()),
        ];
        inputs.push(JsString::from("mixed123 ABC\n".repeat(32)));
        for input in inputs {
            assert_eq!(lower_with(&input, true), lower_with(&input, false));
            assert_eq!(upper_with(&input, true), upper_with(&input, false));
            assert_eq!(title_with(&input, true), title_with(&input, false));
            assert_eq!(
                capitalize_with(&input, true),
                capitalize_with(&input, false)
            );
        }
        assert_eq!(upper(&"ßﬃ".into()), JsString::from("SSFFI"));
        assert_eq!(lower(&"ΟΣ İ".into()), JsString::from("ος i\u{307}"));
        assert_eq!(
            title(&"foo-BAR !HELLO\u{feff}ßETA".into()),
            JsString::from("Foo-bar !hello\u{feff}SSeta")
        );
        assert_eq!(capitalize(&"𐐨abc".into()), JsString::from("𐐨abc"));
    }
}

